-- Ledger V1 phase 9: owner participants, investments and settlements.
-- No participant, investment, policy, tracking month, or settlement is guessed/seeded.

alter table public.ledger_fund_accounts add column is_business_fund boolean not null default true;
update public.ledger_fund_accounts set is_business_fund=false where type='card_clearing';
alter table public.ledger_transactions drop constraint ledger_transactions_type_check;
alter table public.ledger_transactions add constraint ledger_transactions_type_check check(type in('expense','income','sales','transfer','opening','balance_adjustment','investment','owner_settlement','card_settlement','payable_payment','expense_recognition','payroll_payment','prepaid_expense_payment','card_settlement_deposit','correction','owner_settlement_payment'));

create table public.ledger_owner_participants(
 id bigint generated by default as identity primary key,user_id bigint not null references public.users(id)on delete restrict,is_eligible boolean not null,effective_from date not null check(effective_from=date_trunc('month',effective_from)::date),effective_to date null check(effective_to is null or effective_to=(date_trunc('month',effective_to)+interval'1 month'-interval'1 day')::date),sort_order integer not null default 0,created_by bigint not null references public.users(id)on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(effective_to is null or effective_to>=effective_from),unique(user_id,effective_from)
);
create unique index ledger_owner_participants_active_user_idx on public.ledger_owner_participants(user_id)where effective_to is null;
create index ledger_owner_participants_created_by_idx on public.ledger_owner_participants(created_by);
create index ledger_owner_participants_effective_idx on public.ledger_owner_participants(effective_from,effective_to,is_eligible);

create table public.ledger_owner_investments(
 id bigint generated by default as identity primary key,participant_id bigint not null references public.ledger_owner_participants(id)on delete restrict,entry_type text not null check(entry_type in('opening','contribution','adjustment')),signed_amount numeric(16,3)not null check(signed_amount<>0),occurred_at timestamptz not null,transaction_id bigint null unique references public.ledger_transactions(id)on delete restrict,reason text null,source_snapshot jsonb not null default'{}'check(jsonb_typeof(source_snapshot)='object'),created_by bigint not null references public.users(id)on delete restrict,created_at timestamptz not null default now(),check((entry_type='contribution'and signed_amount>0 and transaction_id is not null)or(entry_type in('opening','adjustment')and transaction_id is null)),check(entry_type<>'adjustment'or length(btrim(reason))>0)
);
create index ledger_owner_investments_participant_date_idx on public.ledger_owner_investments(participant_id,occurred_at,id);
create index ledger_owner_investments_created_by_idx on public.ledger_owner_investments(created_by);

create table public.ledger_owner_profit_settings(
 singleton boolean primary key default true check(singleton),profit_tracking_start_month date not null check(profit_tracking_start_month=date_trunc('month',profit_tracking_start_month)::date),opening_undistributed_profit numeric(16,3)not null default 0,created_by bigint not null references public.users(id)on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create index ledger_owner_profit_settings_created_by_idx on public.ledger_owner_profit_settings(created_by);

create table public.ledger_owner_settlement_policies(
 id bigint generated by default as identity primary key,effective_month date not null check(effective_month=date_trunc('month',effective_month)::date),revision integer not null check(revision>0),note text null,created_by bigint not null references public.users(id)on delete restrict,created_at timestamptz not null default now(),unique(effective_month,revision)
);
create index ledger_owner_settlement_policies_created_by_idx on public.ledger_owner_settlement_policies(created_by);
create table public.ledger_owner_settlement_policy_lines(
 id bigint generated by default as identity primary key,policy_id bigint not null references public.ledger_owner_settlement_policies(id)on delete restrict,participant_id bigint not null references public.ledger_owner_participants(id)on delete restrict,settlement_rate numeric(9,6)not null check(settlement_rate>0 and settlement_rate<=1),created_at timestamptz not null default now(),unique(policy_id,participant_id)
);
create index ledger_owner_policy_lines_participant_idx on public.ledger_owner_settlement_policy_lines(participant_id);

create table public.ledger_owner_settlements(
 id bigint generated by default as identity primary key,through_month date not null unique check(through_month=date_trunc('month',through_month)::date),status text not null check(status in('draft','confirmed','partially_paid','paid')),requested_pool numeric(16,3)not null check(requested_pool>0),confirmed_pool numeric(16,3)null check(confirmed_pool is null or confirmed_pool>0),policy_id bigint not null references public.ledger_owner_settlement_policies(id)on delete restrict,policy_snapshot jsonb not null check(jsonb_typeof(policy_snapshot)='object'),undistributed_profit_snapshot numeric(16,3)not null,liquid_funds_snapshot numeric(16,3)not null,reserve_snapshot numeric(16,3)not null,payable_snapshot numeric(16,3)not null,unpaid_owner_settlement_snapshot numeric(16,3)not null,safe_cash_capacity_snapshot numeric(16,3)not null,recommended_max_snapshot numeric(16,3)not null,confirmed_by bigint null references public.users(id)on delete restrict,confirmed_at timestamptz null,created_by bigint not null references public.users(id)on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((status='draft'and confirmed_pool is null and confirmed_by is null and confirmed_at is null)or(status in('confirmed','partially_paid','paid')and confirmed_pool is not null and confirmed_by is not null and confirmed_at is not null))
);
create index ledger_owner_settlements_policy_idx on public.ledger_owner_settlements(policy_id);
create index ledger_owner_settlements_confirmed_by_idx on public.ledger_owner_settlements(confirmed_by);
create index ledger_owner_settlements_created_by_idx on public.ledger_owner_settlements(created_by);

create table public.ledger_owner_settlement_allocations(
 id bigint generated by default as identity primary key,settlement_id bigint not null references public.ledger_owner_settlements(id)on delete restrict,participant_id bigint not null references public.ledger_owner_participants(id)on delete restrict,rate_snapshot numeric(9,6)not null check(rate_snapshot>0 and rate_snapshot<=1),assigned_amount numeric(16,3)not null check(assigned_amount>0),recovery_amount numeric(16,3)not null check(recovery_amount>=0),pure_profit_amount numeric(16,3)not null check(pure_profit_amount>=0),paid_amount numeric(16,3)not null default 0 check(paid_amount>=0),recovery_paid_amount numeric(16,3)not null default 0 check(recovery_paid_amount>=0),pure_profit_paid_amount numeric(16,3)not null default 0 check(pure_profit_paid_amount>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(settlement_id,participant_id),check(assigned_amount=recovery_amount+pure_profit_amount),check(paid_amount=recovery_paid_amount+pure_profit_paid_amount),check(paid_amount<=assigned_amount),check(recovery_paid_amount<=recovery_amount),check(pure_profit_paid_amount<=pure_profit_amount)
);
create index ledger_owner_allocations_participant_idx on public.ledger_owner_settlement_allocations(participant_id);

alter table public.ledger_owner_participants enable row level security;alter table public.ledger_owner_investments enable row level security;alter table public.ledger_owner_profit_settings enable row level security;alter table public.ledger_owner_settlement_policies enable row level security;alter table public.ledger_owner_settlement_policy_lines enable row level security;alter table public.ledger_owner_settlements enable row level security;alter table public.ledger_owner_settlement_allocations enable row level security;
revoke all on table public.ledger_owner_participants,public.ledger_owner_investments,public.ledger_owner_profit_settings,public.ledger_owner_settlement_policies,public.ledger_owner_settlement_policy_lines,public.ledger_owner_settlements,public.ledger_owner_settlement_allocations from public,anon,authenticated,service_role;
revoke all on sequence public.ledger_owner_participants_id_seq,public.ledger_owner_investments_id_seq,public.ledger_owner_settlement_policies_id_seq,public.ledger_owner_settlement_policy_lines_id_seq,public.ledger_owner_settlements_id_seq,public.ledger_owner_settlement_allocations_id_seq from public,anon,authenticated,service_role;
grant select on table public.ledger_owner_participants,public.ledger_owner_investments,public.ledger_owner_profit_settings,public.ledger_owner_settlement_policies,public.ledger_owner_settlement_policy_lines,public.ledger_owner_settlements,public.ledger_owner_settlement_allocations to service_role;

create or replace function public.ledger_owner_role_v1(p_actor bigint)returns boolean language sql stable security definer set search_path=pg_catalog,public as $$select exists(select 1 from public.users where id=p_actor and is_active=true and app_login_enabled=true and lower(role::text)in('owner','master'))$$;
create or replace function public.ledger_owner_policy_at_v1(p_month date)returns bigint language sql stable security definer set search_path=pg_catalog,public as $$select id from public.ledger_owner_settlement_policies where effective_month<=p_month order by effective_month desc,revision desc,id desc limit 1$$;

create or replace function public.ledger_save_owner_participants_v1(p_effective_month date,p_rows jsonb,p_actor_user_id bigint)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare v_row jsonb;v_previous public.ledger_owner_participants%rowtype;v_count int:=0;
begin if not public.ledger_owner_role_v1(p_actor_user_id)then return jsonb_build_object('status','forbidden');end if;if p_effective_month<>date_trunc('month',p_effective_month)::date or jsonb_typeof(p_rows)<>'array'or jsonb_array_length(p_rows)<>3 then return jsonb_build_object('status','participant_count_must_be_3');end if;if(select count(distinct(value->>'userId'))from jsonb_array_elements(p_rows))<>3 then return jsonb_build_object('status','duplicate_participant');end if;
 perform pg_advisory_xact_lock(hashtext('ledger_owner_participants:'||p_effective_month));if exists(select 1 from public.ledger_owner_participants where effective_to is null and effective_from>=p_effective_month)then return jsonb_build_object('status','invalid_effective_month');end if;update public.ledger_owner_participants set effective_to=(p_effective_month-interval'1 day')::date,updated_at=now()where effective_to is null;
 for v_row in select value from jsonb_array_elements(p_rows)order by(value->>'sortOrder')::int,(value->>'userId')::bigint loop if coalesce((v_row->>'isEligible')::boolean,false)=false or not exists(select 1 from public.users where id=(v_row->>'userId')::bigint and lower(role::text)in('owner','master')and is_active=true)then return jsonb_build_object('status','invalid_participant');end if;insert into public.ledger_owner_participants(user_id,is_eligible,effective_from,sort_order,created_by)values((v_row->>'userId')::bigint,true,p_effective_month,(v_row->>'sortOrder')::int,p_actor_user_id);v_count:=v_count+1;end loop;
 insert into public.ledger_audit_logs(actor_user_id,action,entity_type,after_snapshot,reason)values(p_actor_user_id,'owner_participants_version_created','owner_participants',jsonb_build_object('effectiveMonth',p_effective_month,'participants',p_rows),'Explicit settlement participants; no name-based inclusion/exclusion');return jsonb_build_object('status','created','count',v_count);end$$;

create or replace function public.ledger_set_owner_profit_settings_v1(p_tracking_start_month date,p_opening_profit numeric,p_reason text,p_actor_user_id bigint)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare v_before jsonb;begin if not public.ledger_owner_role_v1(p_actor_user_id)then return jsonb_build_object('status','forbidden');end if;if p_tracking_start_month<>date_trunc('month',p_tracking_start_month)::date or p_opening_profit is null or scale(p_opening_profit)>3 or nullif(btrim(p_reason),'')is null then return jsonb_build_object('status','invalid_input');end if;select to_jsonb(s)into v_before from public.ledger_owner_profit_settings s where singleton for update;insert into public.ledger_owner_profit_settings(singleton,profit_tracking_start_month,opening_undistributed_profit,created_by)values(true,p_tracking_start_month,p_opening_profit,p_actor_user_id)on conflict(singleton)do update set profit_tracking_start_month=excluded.profit_tracking_start_month,opening_undistributed_profit=excluded.opening_undistributed_profit,updated_at=now();insert into public.ledger_audit_logs(actor_user_id,action,entity_type,before_snapshot,after_snapshot,reason)values(p_actor_user_id,'owner_profit_settings_saved','owner_profit_settings',v_before,(select to_jsonb(s)from public.ledger_owner_profit_settings s where singleton),btrim(p_reason));return jsonb_build_object('status','saved');end$$;

create or replace function public.ledger_create_owner_investment_v1(p_participant_id bigint,p_entry_type text,p_signed_amount numeric,p_occurred_at timestamptz,p_fund_account_id bigint,p_reason text,p_actor_user_id bigint)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare v_current numeric;v_tx_id bigint;v_id bigint;v_date date;v_operation uuid:=gen_random_uuid();v_owner_user bigint;
begin if not public.ledger_owner_role_v1(p_actor_user_id)then return jsonb_build_object('status','forbidden');end if;if p_entry_type not in('opening','contribution','adjustment')or p_signed_amount=0 or scale(p_signed_amount)>3 or p_occurred_at is null or(p_entry_type='adjustment'and nullif(btrim(p_reason),'')is null)or(p_entry_type in('opening','contribution')and p_signed_amount<0)then return jsonb_build_object('status','invalid_input');end if;select user_id into v_owner_user from public.ledger_owner_participants where id=p_participant_id;if v_owner_user is null then return jsonb_build_object('status','participant_not_found');end if;perform 1 from public.ledger_owner_participants where user_id=v_owner_user order by id for update;select coalesce(sum(i.signed_amount),0)into v_current from public.ledger_owner_investments i join public.ledger_owner_participants p on p.id=i.participant_id where p.user_id=v_owner_user;if v_current+p_signed_amount<0 then return jsonb_build_object('status','negative_cumulative_investment');end if;v_date:=((p_occurred_at at time zone'Asia/Ho_Chi_Minh')-interval'3 hours')::date;
 if p_entry_type='contribution'then if not exists(select 1 from public.ledger_fund_accounts where id=p_fund_account_id and is_active and is_business_fund and type in('cash','bank','personal_custody'))then return jsonb_build_object('status','invalid_fund_account');end if;perform public.ledger_assert_month_open_v1(date_trunc('month',v_date)::date);insert into public.ledger_transactions(operation_id,type,occurred_at,business_date,amount,status,source_type,source_snapshot,memo,created_by,confirmed_by)values(v_operation,'investment',p_occurred_at,v_date,p_signed_amount,'confirmed','owner_investment',jsonb_build_object('participantId',p_participant_id,'entryType',p_entry_type),nullif(btrim(p_reason),''),p_actor_user_id,p_actor_user_id)returning id into v_tx_id;insert into public.ledger_movements(transaction_id,fund_account_id,amount)values(v_tx_id,p_fund_account_id,p_signed_amount);end if;
 insert into public.ledger_owner_investments(participant_id,entry_type,signed_amount,occurred_at,transaction_id,reason,source_snapshot,created_by)values(p_participant_id,p_entry_type,p_signed_amount,p_occurred_at,v_tx_id,nullif(btrim(p_reason),''),jsonb_build_object('cumulativeBefore',v_current,'cumulativeAfter',v_current+p_signed_amount,'fundAccountId',p_fund_account_id),p_actor_user_id)returning id into v_id;insert into public.ledger_audit_logs(actor_user_id,action,entity_type,entity_id,before_snapshot,after_snapshot,reason)values(p_actor_user_id,'owner_investment_created','owner_investment',v_id,jsonb_build_object('cumulativeInvestment',v_current),jsonb_build_object('entryType',p_entry_type,'amount',p_signed_amount,'cumulativeInvestment',v_current+p_signed_amount,'transactionId',v_tx_id),nullif(btrim(p_reason),''));return jsonb_build_object('status','created','investmentId',v_id,'transactionId',v_tx_id);end$$;

create or replace function public.ledger_create_owner_policy_v1(p_effective_month date,p_lines jsonb,p_note text,p_actor_user_id bigint)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare v_id bigint;v_revision int;v_row jsonb;v_sum numeric;begin if not public.ledger_owner_role_v1(p_actor_user_id)then return jsonb_build_object('status','forbidden');end if;if p_effective_month<>date_trunc('month',p_effective_month)::date or jsonb_typeof(p_lines)<>'array'or jsonb_array_length(p_lines)<>3 then return jsonb_build_object('status','participant_count_must_be_3');end if;select sum((value->>'rate')::numeric)into v_sum from jsonb_array_elements(p_lines);if v_sum<>1.000000 then return jsonb_build_object('status','rates_must_equal_100');end if;if(select count(distinct(value->>'participantId'))from jsonb_array_elements(p_lines))<>3 or exists(select 1 from jsonb_array_elements(p_lines)r where not exists(select 1 from public.ledger_owner_participants p where p.id=(r->>'participantId')::bigint and p.is_eligible and p.effective_from<=p_effective_month and(p.effective_to is null or p.effective_to>=p_effective_month)))then return jsonb_build_object('status','invalid_participants');end if;perform pg_advisory_xact_lock(hashtext('ledger_owner_policy:'||p_effective_month));select coalesce(max(revision),0)+1 into v_revision from public.ledger_owner_settlement_policies where effective_month=p_effective_month;insert into public.ledger_owner_settlement_policies(effective_month,revision,note,created_by)values(p_effective_month,v_revision,nullif(btrim(p_note),''),p_actor_user_id)returning id into v_id;for v_row in select value from jsonb_array_elements(p_lines)loop insert into public.ledger_owner_settlement_policy_lines(policy_id,participant_id,settlement_rate)values(v_id,(v_row->>'participantId')::bigint,(v_row->>'rate')::numeric);end loop;insert into public.ledger_audit_logs(actor_user_id,action,entity_type,entity_id,after_snapshot,reason)values(p_actor_user_id,'owner_settlement_policy_created','owner_settlement_policy',v_id,jsonb_build_object('effectiveMonth',p_effective_month,'revision',v_revision,'lines',p_lines),nullif(btrim(p_note),''));return jsonb_build_object('status','created','policyId',v_id,'revision',v_revision);end$$;

create or replace function public.ledger_owner_financial_capacity_v1(p_through_month date)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare v_start date;v_opening numeric;v_profit numeric;v_settled numeric;v_liquid numeric;v_reserve numeric;v_payable numeric;v_owner_unpaid numeric;v_safe numeric;v_undistributed numeric;begin select profit_tracking_start_month,opening_undistributed_profit into v_start,v_opening from public.ledger_owner_profit_settings where singleton;if v_start is null then return jsonb_build_object('status','profit_tracking_not_configured');end if;select coalesce(sum((summary_snapshot#>>'{operatingResult,operatingProfit}')::numeric),0)into v_profit from public.ledger_month_closures where month between v_start and p_through_month;select coalesce(sum(confirmed_pool),0)into v_settled from public.ledger_owner_settlements where status in('confirmed','partially_paid','paid');v_undistributed:=v_opening+v_profit-v_settled;select coalesce(sum(m.amount),0)into v_liquid from public.ledger_movements m join public.ledger_transactions t on t.id=m.transaction_id join public.ledger_fund_accounts f on f.id=m.fund_account_id where t.status='confirmed'and f.is_active and f.is_business_fund and f.type in('cash','bank','personal_custody');select coalesce(sum(case entry_type when'allocate'then amount when'release'then-amount when'consume'then-amount else amount end),0)into v_reserve from public.ledger_reserve_entries;select coalesce(sum(greatest(0,p.original_amount-coalesce((select sum(a.allocated_amount)from public.ledger_payable_allocations a where a.payable_id=p.id),0))),0)into v_payable from public.ledger_payables p where p.status<>'cancelled';select coalesce(sum(a.assigned_amount-a.paid_amount),0)into v_owner_unpaid from public.ledger_owner_settlement_allocations a join public.ledger_owner_settlements s on s.id=a.settlement_id where s.status in('confirmed','partially_paid');v_safe:=greatest(0,v_liquid-v_reserve-v_payable-v_owner_unpaid);return jsonb_build_object('status','ok','throughMonth',p_through_month,'openingUndistributedProfit',v_opening,'closedOperatingProfit',v_profit,'confirmedSettlementPool',v_settled,'undistributedProfit',v_undistributed,'liquidFunds',v_liquid,'activeReserve',v_reserve,'vendorPayables',v_payable,'confirmedUnpaidOwnerSettlements',v_owner_unpaid,'safeCashCapacity',v_safe,'recommendedMax',greatest(0,least(v_undistributed,v_safe)));end$$;

create or replace function public.ledger_confirm_owner_settlement_v1(p_through_month date,p_requested_pool numeric,p_actor_user_id bigint)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare v_capacity jsonb;v_policy bigint;v_count int;v_rate_sum numeric;v_settlement bigint;v_line record;v_assigned numeric;v_allocated numeric:=0;v_invested numeric;v_recovered numeric;v_recovery numeric;v_index int:=0;v_snapshot jsonb:='[]';begin if not public.ledger_owner_role_v1(p_actor_user_id)then return jsonb_build_object('status','forbidden');end if;if not public.ledger_month_is_closed_v1(p_through_month)then return jsonb_build_object('status','through_month_not_closed');end if;if p_requested_pool<=0 or scale(p_requested_pool)>3 then return jsonb_build_object('status','invalid_pool');end if;perform pg_advisory_xact_lock(hashtext('ledger_owner_settlement:'||p_through_month));if exists(select 1 from public.ledger_owner_settlements where through_month=p_through_month)then return jsonb_build_object('status','duplicate_through_month');end if;v_capacity:=public.ledger_owner_financial_capacity_v1(p_through_month);if v_capacity->>'status'<>'ok'then return jsonb_build_object('status','OWNER_PROFIT_TRACKING_NOT_CONFIGURED');end if;if p_requested_pool>(v_capacity->>'recommendedMax')::numeric then return jsonb_build_object('status','requested_above_recommended_max','recommendedMax',v_capacity->'recommendedMax');end if;v_policy:=public.ledger_owner_policy_at_v1(p_through_month);if v_policy is null then return jsonb_build_object('status','policy_not_configured');end if;select count(*),sum(settlement_rate)into v_count,v_rate_sum from public.ledger_owner_settlement_policy_lines where policy_id=v_policy;if v_count<>3 or v_rate_sum<>1.000000 then return jsonb_build_object('status','invalid_policy');end if;
 insert into public.ledger_owner_settlements(through_month,status,requested_pool,confirmed_pool,policy_id,policy_snapshot,undistributed_profit_snapshot,liquid_funds_snapshot,reserve_snapshot,payable_snapshot,unpaid_owner_settlement_snapshot,safe_cash_capacity_snapshot,recommended_max_snapshot,confirmed_by,confirmed_at,created_by)values(p_through_month,'confirmed',p_requested_pool,p_requested_pool,v_policy,'{}',(v_capacity->>'undistributedProfit')::numeric,(v_capacity->>'liquidFunds')::numeric,(v_capacity->>'activeReserve')::numeric,(v_capacity->>'vendorPayables')::numeric,(v_capacity->>'confirmedUnpaidOwnerSettlements')::numeric,(v_capacity->>'safeCashCapacity')::numeric,(v_capacity->>'recommendedMax')::numeric,p_actor_user_id,now(),p_actor_user_id)returning id into v_settlement;
 for v_line in select l.*,p.sort_order,u.id user_id,coalesce(u.name,u.full_name,u.username)participant_name from public.ledger_owner_settlement_policy_lines l join public.ledger_owner_participants p on p.id=l.participant_id join public.users u on u.id=p.user_id where l.policy_id=v_policy order by p.sort_order,p.id loop v_index:=v_index+1;if v_index=v_count then v_assigned:=p_requested_pool-v_allocated;else v_assigned:=trunc(p_requested_pool*v_line.settlement_rate,3);end if;v_allocated:=v_allocated+v_assigned;select coalesce(sum(i.signed_amount),0)into v_invested from public.ledger_owner_investments i join public.ledger_owner_participants ip on ip.id=i.participant_id where ip.user_id=v_line.user_id;select coalesce(sum(a.recovery_amount),0)into v_recovered from public.ledger_owner_settlement_allocations a join public.ledger_owner_settlements s on s.id=a.settlement_id join public.ledger_owner_participants ap on ap.id=a.participant_id where ap.user_id=v_line.user_id and s.status in('confirmed','partially_paid','paid');v_recovery:=least(v_assigned,greatest(0,v_invested-v_recovered));insert into public.ledger_owner_settlement_allocations(settlement_id,participant_id,rate_snapshot,assigned_amount,recovery_amount,pure_profit_amount)values(v_settlement,v_line.participant_id,v_line.settlement_rate,v_assigned,v_recovery,v_assigned-v_recovery);v_snapshot:=v_snapshot||jsonb_build_array(jsonb_build_object('participantId',v_line.participant_id,'userId',v_line.user_id,'name',v_line.participant_name,'sortOrder',v_line.sort_order,'rate',v_line.settlement_rate,'assignedAmount',v_assigned,'recoveryAmount',v_recovery,'pureProfitAmount',v_assigned-v_recovery,'cumulativeInvestment',v_invested,'priorRecoveryAllocated',v_recovered));end loop;update public.ledger_owner_settlements set policy_snapshot=jsonb_build_object('policyId',v_policy,'lines',v_snapshot)where id=v_settlement;insert into public.ledger_audit_logs(actor_user_id,action,entity_type,entity_id,after_snapshot,reason)values(p_actor_user_id,'owner_settlement_confirmed','owner_settlement',v_settlement,jsonb_build_object('capacity',v_capacity,'policyId',v_policy,'allocations',v_snapshot),'Closed-profit owner settlement confirmed; no fund movement');return jsonb_build_object('status','confirmed','settlementId',v_settlement,'confirmedPool',p_requested_pool,'allocations',v_snapshot,'capacity',v_capacity);end$$;

create or replace function public.ledger_pay_owner_allocation_v1(p_allocation_id bigint,p_amount numeric,p_fund_account_id bigint,p_paid_at timestamptz,p_memo text,p_actor_user_id bigint)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare v_allocation public.ledger_owner_settlement_allocations%rowtype;v_settlement public.ledger_owner_settlements%rowtype;v_balance numeric;v_remaining_recovery numeric;v_recovery_paid numeric;v_profit_paid numeric;v_tx bigint;v_date date;v_total_paid numeric;begin if not public.ledger_owner_role_v1(p_actor_user_id)then return jsonb_build_object('status','forbidden');end if;if p_amount<=0 or scale(p_amount)>3 or p_paid_at is null then return jsonb_build_object('status','invalid_amount');end if;select*into v_allocation from public.ledger_owner_settlement_allocations where id=p_allocation_id for update;if v_allocation.id is null then return jsonb_build_object('status','allocation_not_found');end if;select*into v_settlement from public.ledger_owner_settlements where id=v_allocation.settlement_id for update;if v_settlement.status not in('confirmed','partially_paid')or v_allocation.paid_amount+p_amount>v_allocation.assigned_amount then return jsonb_build_object('status','overpayment');end if;if not exists(select 1 from public.ledger_fund_accounts where id=p_fund_account_id and is_active and is_business_fund and type in('cash','bank','personal_custody'))then return jsonb_build_object('status','invalid_fund_account');end if;select coalesce(sum(m.amount),0)into v_balance from public.ledger_movements m join public.ledger_transactions t on t.id=m.transaction_id where m.fund_account_id=p_fund_account_id and t.status='confirmed'and t.occurred_at<=now();if v_balance<p_amount then return jsonb_build_object('status','insufficient_fund','balance',v_balance);end if;v_date:=((p_paid_at at time zone'Asia/Ho_Chi_Minh')-interval'3 hours')::date;perform public.ledger_assert_month_open_v1(date_trunc('month',v_date)::date);v_remaining_recovery:=v_allocation.recovery_amount-v_allocation.recovery_paid_amount;v_recovery_paid:=least(p_amount,v_remaining_recovery);v_profit_paid:=p_amount-v_recovery_paid;insert into public.ledger_transactions(operation_id,type,occurred_at,business_date,amount,party_id,status,source_type,source_snapshot,memo,created_by,confirmed_by)values(gen_random_uuid(),'owner_settlement_payment',p_paid_at,v_date,p_amount,null,'confirmed','owner_settlement_payment',jsonb_build_object('settlementId',v_settlement.id,'allocationId',v_allocation.id,'participantId',v_allocation.participant_id,'assignedAmount',v_allocation.assigned_amount,'paymentBefore',v_allocation.paid_amount,'paymentAfter',v_allocation.paid_amount+p_amount,'recoveryPaid',v_recovery_paid,'pureProfitPaid',v_profit_paid),nullif(btrim(p_memo),''),p_actor_user_id,p_actor_user_id)returning id into v_tx;insert into public.ledger_movements(transaction_id,fund_account_id,amount)values(v_tx,p_fund_account_id,-p_amount);update public.ledger_owner_settlement_allocations set paid_amount=paid_amount+p_amount,recovery_paid_amount=recovery_paid_amount+v_recovery_paid,pure_profit_paid_amount=pure_profit_paid_amount+v_profit_paid,updated_at=now()where id=v_allocation.id;select sum(paid_amount)into v_total_paid from public.ledger_owner_settlement_allocations where settlement_id=v_settlement.id;update public.ledger_owner_settlements set status=case when v_total_paid=confirmed_pool then'paid'else'partially_paid'end,updated_at=now()where id=v_settlement.id;insert into public.ledger_audit_logs(actor_user_id,action,entity_type,entity_id,before_snapshot,after_snapshot,reason)values(p_actor_user_id,'owner_settlement_payment_created','owner_settlement_allocation',v_allocation.id,to_jsonb(v_allocation),jsonb_build_object('transactionId',v_tx,'amount',p_amount,'fundAccountId',p_fund_account_id,'recoveryPaid',v_recovery_paid,'pureProfitPaid',v_profit_paid,'settlementTotalPaid',v_total_paid),nullif(btrim(p_memo),''));return jsonb_build_object('status','paid','transactionId',v_tx,'recoveryPaid',v_recovery_paid,'pureProfitPaid',v_profit_paid,'settlementStatus',case when v_total_paid=v_settlement.confirmed_pool then'paid'else'partially_paid'end);end$$;

create or replace function public.ledger_owner_payment_fund_guard_v1()returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$
declare v_type text;v_balance numeric;
begin
 select type into v_type from public.ledger_transactions where id=new.transaction_id;
 if v_type='owner_settlement_payment'and new.amount<0 then
  perform pg_advisory_xact_lock(hashtext('ledger_fund_balance:'||new.fund_account_id));
  select coalesce(sum(m.amount),0)into v_balance from public.ledger_movements m join public.ledger_transactions t on t.id=m.transaction_id where m.fund_account_id=new.fund_account_id and t.status='confirmed'and t.occurred_at<=now();
  if v_balance+new.amount<0 then raise exception using errcode='P0001',message='OWNER_SETTLEMENT_INSUFFICIENT_FUND';end if;
 end if;
 return new;
end$$;
create trigger ledger_owner_payment_fund_guard before insert on public.ledger_movements for each row execute function public.ledger_owner_payment_fund_guard_v1();

revoke all on function public.ledger_owner_role_v1(bigint),public.ledger_owner_policy_at_v1(date),public.ledger_save_owner_participants_v1(date,jsonb,bigint),public.ledger_set_owner_profit_settings_v1(date,numeric,text,bigint),public.ledger_create_owner_investment_v1(bigint,text,numeric,timestamptz,bigint,text,bigint),public.ledger_create_owner_policy_v1(date,jsonb,text,bigint),public.ledger_owner_financial_capacity_v1(date),public.ledger_confirm_owner_settlement_v1(date,numeric,bigint),public.ledger_pay_owner_allocation_v1(bigint,numeric,bigint,timestamptz,text,bigint)from public,anon,authenticated;
revoke all on function public.ledger_owner_payment_fund_guard_v1()from public,anon,authenticated,service_role;
grant execute on function public.ledger_owner_role_v1(bigint),public.ledger_owner_policy_at_v1(date),public.ledger_save_owner_participants_v1(date,jsonb,bigint),public.ledger_set_owner_profit_settings_v1(date,numeric,text,bigint),public.ledger_create_owner_investment_v1(bigint,text,numeric,timestamptz,bigint,text,bigint),public.ledger_create_owner_policy_v1(date,jsonb,text,bigint),public.ledger_owner_financial_capacity_v1(date),public.ledger_confirm_owner_settlement_v1(date,numeric,bigint),public.ledger_pay_owner_allocation_v1(bigint,numeric,bigint,timestamptz,text,bigint)to service_role;

comment on table public.ledger_owner_participants is 'Explicit settlement eligibility; names are never business rules.';
comment on table public.ledger_owner_investments is 'Investment basis is separate from settlement policy and P&L.';
comment on table public.ledger_owner_settlements is 'Confirmation creates an owner obligation without a fund movement or expense.';
